package main

import (
	"crypto/tls"
	"fmt"
	"net"
	"net/smtp"
	"strings"
	"sync"
	"time"
)

type CircuitState int

const (
	Closed CircuitState = iota
	Open
	HalfOpen
)

type CircuitBreaker struct {
	mu           sync.Mutex
	state        CircuitState
	failures     int
	threshold    int
	resetTimeout time.Duration
	lastFailure  time.Time
}

func NewCircuitBreaker(threshold int, timeout time.Duration) *CircuitBreaker {
	return &CircuitBreaker{
		state:        Closed,
		threshold:    threshold,
		resetTimeout: timeout,
	}
}

func (cb *CircuitBreaker) Execute(fn func() error) error {
	cb.mu.Lock()
	if cb.state == Open {
		if time.Since(cb.lastFailure) > cb.resetTimeout {
			cb.state = HalfOpen
		} else {
			cb.mu.Unlock()
			return fmt.Errorf("circuit breaker is open")
		}
	}
	cb.mu.Unlock()

	err := fn()

	cb.mu.Lock()
	defer cb.mu.Unlock()
	if err != nil {
		cb.failures++
		cb.lastFailure = time.Now()
		if cb.failures >= cb.threshold {
			cb.state = Open
		}
		return err
	}
	cb.failures = 0
	cb.state = Closed
	return nil
}

type EmailService struct {
	smtpHost       string
	smtpPort       string
	username       string
	password       string
	circuitBreaker *CircuitBreaker
	allowedDomains []string
}

func NewEmailService(host, port, user, pass string, domains []string) *EmailService {
	return &EmailService{
		smtpHost:       host,
		smtpPort:       port,
		username:       user,
		password:       pass,
		circuitBreaker: NewCircuitBreaker(5, 30*time.Second),
		allowedDomains: domains,
	}
}

// isASCIIOnly strictly validates that domain contains only ASCII letters, digits, dots, hyphens
func isASCIIOnly(domain string) bool {
	for _, r := range domain {
		if r > 127 {
			return false
		}
		if !((r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '.' || r == '-') {
			return false
		}
	}
	return true
}

// containsCRLF reports whether s contains carriage return or line feed characters,
// which could be used for header injection.
func containsCRLF(s string) bool {
	return strings.ContainsAny(s, "\r\n")
}

func (es *EmailService) ValidateRecipient(email string) error {
	parts := strings.SplitN(email, "@", 2)
	if len(parts) != 2 {
		return fmt.Errorf("invalid email format")
	}

	local := parts[0]
	domain := strings.ToLower(parts[1])

	// Reject any CR/LF in the recipient to prevent header injection.
	if containsCRLF(email) {
		return fmt.Errorf("recipient contains invalid characters")
	}

	// Reject any non-ASCII in local part
	for _, r := range local {
		if r > 127 {
			return fmt.Errorf("local part contains non-ASCII characters")
		}
	}

	// Strict ASCII-only check prevents all homograph attacks
	if !isASCIIOnly(domain) {
		return fmt.Errorf("domain contains non-ASCII characters - potential homograph attack")
	}

	// Direct comparison - safe because we already ensured ASCII-only
	for _, allowed := range es.allowedDomains {
		if domain == allowed {
			return nil
		}
	}

	return fmt.Errorf("domain %s is not in the allowed list", domain)
}

func (es *EmailService) SendEmail(to, subject, body string) error {
	if err := es.ValidateRecipient(to); err != nil {
		return fmt.Errorf("recipient validation failed: %w", err)
	}

	// Reject CR/LF in the subject header to prevent header injection.
	if containsCRLF(subject) {
		return fmt.Errorf("subject contains invalid characters")
	}

	return es.circuitBreaker.Execute(func() error {
		return es.doSend(to, subject, body)
	})
}

func (es *EmailService) doSend(to, subject, body string) error {
	addr := net.JoinHostPort(es.smtpHost, es.smtpPort)

	tlsConfig := &tls.Config{
		ServerName: es.smtpHost,
	}

	conn, err := tls.Dial("tcp", addr, tlsConfig)
	if err != nil {
		return fmt.Errorf("TLS connection failed: %w", err)
	}
	defer conn.Close()

	client, err := smtp.NewClient(conn, es.smtpHost)
	if err != nil {
		return fmt.Errorf("SMTP client creation failed: %w", err)
	}
	defer client.Close()

	auth := smtp.PlainAuth("", es.username, es.password, es.smtpHost)
	if err := client.Auth(auth); err != nil {
		return fmt.Errorf("authentication failed: %w", err)
	}

	if err := client.Mail(es.username); err != nil {
		return err
	}
	if err := client.Rcpt(to); err != nil {
		return err
	}

	w, err := client.Data()
	if err != nil {
		return err
	}

	msg := fmt.Sprintf("From: %s\r\nTo: %s\r\nSubject: %s\r\n\r\n%s",
		es.username, to, subject, body)
	_, err = w.Write([]byte(msg))
	if err != nil {
		return err
	}

	return w.Close()
}

func main() {
	allowedDomains := []string{"company.com", "partner.org", "trusted.net"}
	service := NewEmailService("smtp.company.com", "465", "noreply@company.com", "secret", allowedDomains)

	err := service.SendEmail("user@company.com", "Test", "Hello")
	if err != nil {
		fmt.Printf("Error: %v\n", err)
	}
}
